on handleConsoleCommands(): void { global $argc, $argv; if (isset($argc) && isset($argv)) { ini_set('error_log', getLogPath() . 'error_cli.log'); error_log('Запуск через консоль, параметры: ' . print_r($argv, true)); $_REQUEST['uniquesession'] = true; if ($argc === 2) { $_REQUEST['norpc'] = $argv[1]; } else if ($argc >= 3) { $_REQUEST['config'] = $argv[1]; $_REQUEST['norpc'] = $argv[2]; $args = array_slice($argv, 3); foreach($args as $k => $v) { if (!empty($v) && is_string($v) && safe_strpos($v, '=') !== false) { parse_str($v, $arr); $args[$k] = (object)$arr; } } $_REQUEST['argscmd'] = $args; } } else { ini_set('error_log', getLogPath() . 'error.log'); } } function suspendJsonRpc(): void { global $suspendedJsonRpcExecute, $notExecute; $suspendedJsonRpcExecute = isset($suspendedJsonRpcExecute) ? $suspendedJsonRpcExecute + 1 : 1; $notExecute = true; } function resumeJsonRpc(): void { global $suspendedJsonRpcExecute, $notExecute; $suspendedJsonRpcExecute = isset($suspendedJsonRpcExecute) ? $suspendedJsonRpcExecute - 1 : 0; $notExecute = $suspendedJsonRpcExecute !== 0; } function handleJsonRpc($className): bool { global $notExecute; if (!isset($notExecute) || !$notExecute) { if (isset($_REQUEST['norpc']) && is_string($_REQUEST['norpc'])) { $class = new $className; if (!empty($_REQUEST['argscmd'])) { $class->{$_REQUEST['norpc']}(...$_REQUEST['argscmd']); } else { $params = new \stdClass; foreach ($_REQUEST as $var => $value) { if ($var !== 'session' && $var !== 'norpc' && $var !== 'uniquesession') { $params->{$var} = $value; } } $class->{$_REQUEST['norpc']}($params); } return true; } else if (filter_input(INPUT_SERVER, 'REQUEST_METHOD') === 'POST') { $service = new Junior\Server(new $className); $service->process(); return true; } } return false; } function getRequestHeaders(bool $isKeysLowerCase = false): false|array { if(function_exists('apache_request_headers')) { $arh = apache_request_headers(); } else { $arh = array(); $rx_http = '/\AHTTP_/'; foreach($_SERVER as $ke